-- 몬스터에게서 드랍되는 얼음 팩을 5개 모아오면 시크루트 버프 7종을 걸어주는 이벤트
-- 한국 : 버프 3시간 , 시크루트 유저들을 위한 꿀빵과 꿀물 선택 가능
-- 일본 : 버프 2시간 , 꿀빵 , 꿀물 제외



function NPC_Kores_summer_Event_contact()

	-- 국가 코드 읽어오기
		-- get_local_info()의 반환값들
		--LOCAL_INFO_KOREA                      = 1
		--LOCAL_INFO_HONGKONG                   = 2
		--LOCAL_INFO_AMERICA                    = 4
		--LOCAL_INFO_EUROPE                     = 8
		--LOCAL_INFO_JAPAN                      = 16
		--LOCAL_INFO_TAIWAN                     = 32
		--LOCAL_INFO_CHINA                      = 64
	
	local state_code = get_local_info() 
			
	-- 국가코드=1 즉 , 한국일 경우
	if state_code == 1 then
	
		-- 다이얼로그 출력
		dlg_title( "@90995301" )
		dlg_text( "@90995302" )
	
		-- 얼음 팩 강화 마법 교환
		dlg_menu( "@90010220", "summer_event_Buff()" )
		-- 얼음 팩 아이템 교환 : 꿀빵 , 꿀물
		dlg_menu( "@90010228", "summer_event_item()" )
	else
		
		-- 국가코드 = 16 즉 , 일본일 경우
		if state_code == 16 then
		
			-- 다이얼로그 출력
			dlg_title( "@90995301" )
			dlg_text( "@90995310" )
		
			-- 얼음 팩 강화 마법 교환
			dlg_menu( "@90010220", "summer_event_Buff()" )
		
		end -- if state_code == 16 then
	
	end -- if state_code == 1 then

	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()

end


