function RunTeleport_Wonderland()
 -- 여기에 텔레포트 조건을 추가 

    -- RunTeleport( 0, 180876 , 13221 )
    -- 1~30레벨 공동묘지1
    if get_value( "level" ) < 31 then
    RunTeleport( 0 , 180876 , 13221 )
    -- 31~60레벨 공동묘지2
    elseif ( get_value( "level" ) > 30 )  and ( get_value( "level" ) < 61 ) then 
    RunTeleport( 0 , 148620 , 13221 )
    -- 61~90레벨 공동묘지3
    elseif ( get_value( "level" ) > 60 )  and ( get_value( "level" ) < 91 ) then
    RunTeleport( 0 , 116364 , 13221 )
    -- 91~120레벨 나이트메어1
    elseif ( get_value( "level" ) > 90 )  and ( get_value( "level" ) < 121 ) then 
    RunTeleport( 0 , 203590 , 15059 )
    -- 121~170레벨 나이트메어2
    elseif ( get_value( "level" ) > 120 )  and ( get_value( "level" ) < 200 ) then 
    RunTeleport( 0 , 171334 , 15059 )
    end
   
end




