function npc_wonderland_teleport_contact()

	local start_channel, end_channel
				
	-- 이동 가능한 채널 갯수 확인 및 이동 가능할 경우의 시작 번호와 끝 번호의 변수 정의
	--start_channel = get_min_channel_num(  ) -- 이동 가능한 채널 번호의 시작번호
	--end_channel = get_max_channel_num(  ) -- 이동 가능한 채널 번호의 종료번호
	
	-- 지역 npc id 가져오기
	local npc_id = get_npc_id()
	 
	-- <이름 출력> 각 npc의 이름을 출력해 준다.
    -- 공동묘지01 츄이일 때 ( 9985 )
    if npc_id == 9985 then
           dlg_title( "@90996801" )
           start_channel = get_min_channel_num( 110000 )
           end_channel = get_max_channel_num( 110000 )
	-- 공동묘지02 츄이일 때 ( 9983 )
	elseif npc_id == 9983 then
	       dlg_title( "@90996801" )
	       start_channel = get_min_channel_num( 90000 )
	       end_channel = get_max_channel_num( 90000 )
	-- 공동묘지03 츄이일 때 ( 9982 )
	elseif npc_id == 9982 then
	       dlg_title( "@90996801" )
	       start_channel = get_min_channel_num( 70000 )
	       end_channel = get_max_channel_num( 70000 )
	-- 나이트메어01 츄이일 때 ( 9986 )
	elseif npc_id == 9986 then
	       dlg_title( "@90996801" )
	       start_channel = get_min_channel_num( 120000 )
	       end_channel = get_max_channel_num( 120000 )
	-- 나이트메어02 ( 9984 )
	elseif npc_id == 9984 then
	       dlg_title( "@90996801" )
	       start_channel = get_min_channel_num( 100000 )
	       end_channel = get_max_channel_num( 100000 )
		   
	elseif npc_id == 10043 then
	       dlg_title( "@90996801" )
	       start_channel = get_min_channel_num( 70000 )
	       end_channel = get_max_channel_num( 70000 )
		   
	end -- if 끝
    --텔레포터 츄이들이 공통으로 사용하는 인사말 출력

	-- 임시 변수 선언과 동시에 NPC ID 가져오기
	--local npc_id = get_npc_id()

	-- 다이얼로그 출력
	-- 할로윈 이벤트 텔레포트 npc일 때
	--if npc_id == 9982 then
	--	dlg_title( "@90301601" )
	dlg_text( "@90996817" )
	--dlg_show()
	--end
	

	-- 이동 가능한 채널이 없을 경우의 다이얼로그 출력
	if end_channel == 1 then
		dlg_text( "@90300516" )
	elseif end_channel > 1 then
		text = sconv("@90300514", "#@number1@#", tostring( 1 ) , "#@number2@#",tostring( end_channel - start_channel + 1 ))   -- 변수를 실제 값(스트링)으로 치환 시킨다.
		dlg_text( text )       -- 대사창에 텍스트 삽입
	end
		
			
	--메뉴 구성 (이동 가능 여부에 따른 메뉴 구성)
			
	-- 채널이동이 불가능할 경우
	-- if end_channel == 1 then
		-- 돌아가기 텍스트
		-- if npc_id == 9982 then/run refresh("script")
	--		dlg_menu( "@90010003", " " )
	--	end	

	-- 채널이동이 가능할 경우
	if end_channel > 1 then
		-- 채널 번호 입력 텍스트박스 호출(채널이동)
		dlg_menu( "@90300513", "show_channel_set()" )
	end

	if get_value( "level" ) < 16 then
		dlg_menu( "@70100300", 'RunTeleport_Begin_TO_City( 0 , 172178 , 51480 )' )
	end  --
	
	-- 40레벨 이상일 경우 론도까지 보여준다.
	if get_value( "level" ) > 39 then
	    dlg_menu( "@70000010", 'RunTeleport( 0 , 6736 , 6701 )' ) -- 라크시
	    dlg_menu( "@70070301", 'RunTeleport( 0 , 116567 , 57806 )' ) -- 카탄
		dlg_menu( "@70090401", 'RunTeleport( 0 , 153653 , 76524 )' ) -- 호라이즌
		dlg_menu( "@100006024", 'RunTeleport( 0 , 136199 , 104892 )' ) -- 론도
	end
	
	-- 40레벨 미만일 경우, 론도는 보여지지 않는다.
	if ( get_value( "level" ) < 40 ) and ( get_value( "level" ) > 15 ) then
	    dlg_menu( "@70000010", 'RunTeleport( 0 , 6736 , 6701 )' ) -- 라크시
	    dlg_menu( "@70070301", 'RunTeleport( 0 , 116567 , 57806 )' ) -- 카탄
		dlg_menu( "@70090401", 'RunTeleport( 0 , 153653 , 76524 )' ) -- 호라이즌
	end
		-- 대화종료 
	dlg_menu( "@90010002", " " )
 
	dlg_show()
    
end




            


