-- 보물 얻기
function beginner_event_exchange()

	-- 창세신석이 있나 확인
	local item_count = find_item ( 2000277 )
	item_handle = get_item_handle ( 2000277 )

	-- 보상을 받은 적 있는지 체크
	local q_flag0 = tonumber( get_flag( "q20" ) )

	if q_flag0 == nil then
		q_flag0 = 0
		set_flag( "q20", "0" )
	end
	
	if item_count >= 1 then
		-- 레벨 받아옴
		local level = get_value( "level" )
		
		if level <= 1 then
			
			-- 보상을 받은 적 있는지 체크
			-- 이미 보상을 받았으면 출력
			if q_flag0 >= 1 then
			      dlg_title( "@90996911" )
			      dlg_text( "@90996920" ) 
			 -- 보상을 아직 받지 못했을 때
			else
			       -- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				insert_item ( 2000259, 1 )
				set_flag( "q20", "1" )
			end
			
		elseif level >= 2 and level <= 10 then
			
			-- 이미 보상을 받았으면 출력
			if q_flag0 >= 2 then
			      dlg_title( "@90996911" )
			      dlg_text( "@90996920" ) 
			 -- 보상을 아직 받지 못했을 때
			else
			       -- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				insert_item ( 2000262, 1 )
				set_flag( "q20", "2" )
			end
			
		elseif level >= 11 and level <= 20 then
			
			-- 이미 보상을 받았으면 출력
			if q_flag0 >= 3 then
				dlg_title( "@90996911" )
				dlg_text( "@90996920" )
			-- 보상을 아직 받지 못했을 때   
			else
			       -- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				insert_item ( 2000265, 1 )
				set_flag( "q20", "3" )
			end
			
		elseif level >= 21 and level <= 30 then
			
			   -- 이미 보상을 받았으면 출력
			if q_flag0 >= 4 then
			      dlg_title( "@90996911" )
			      dlg_text( "@90996920" )
				-- 보상을 아직 받지 못했을 때  
			else
				-- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				insert_item ( 2000268, 1 )
				set_flag( "q20", "4" )
			end
			
		elseif level >= 31 and level <= 40 then
			
			-- 이미 보상을 받았으면 출력
			if q_flag0 >= 5 then
			      dlg_title( "@90996911" )
			      dlg_text( "@90996920" )
			-- 보상을 아직 받지 못했을 때  
			else
			       -- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				insert_item ( 2000271, 1 )
				set_flag( "q20", "5" )
			end
			
		elseif level >= 41 and level <= 50 then
			
			-- 이미 보상을 받았으면 출력
			if q_flag0 >= 6 then
				dlg_title( "@90996911" )
				dlg_text( "@90996920" )
			-- 보상을 아직 받지 못했을 때  
			else
				-- 창세신석 가지고 있을 때(신주창세 선물상자 지급)
				dlg_title( "@90996911" )
				dlg_text( "@90996913" )
				delete_item ( item_handle, 50 )
				insert_item ( 2000274, 1 )
				set_flag( "q20", "6" )
			end
		else
			-- 카드가 없을 경우
			dlg_title( "@90996911" )
			dlg_text( "@90996916" )
		end
				
	elseif item_count == 0 then
				-- 카드가 없을 경우
			dlg_title( "@90996911" )
			dlg_text( "@90996916" )		
	end
	
	--돌아가기
	dlg_menu( "@90010003", 'NPC_beginner_event_contact()' )		
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
end
	
















