end



-- 하트캔디 교환 메뉴 선택 
function valentine_event_Buff()

	-- 다이얼로그 출력
	dlg_title( "@90996995" )		--NPC 이름 발렌타인 이벤트 발렌티나
	dlg_text( "@90996998" )			--NPC 대사

	-- 교환 메뉴 출력
	dlg_menu ( "@90996999", "valentine_event_operation(1)" )		-- 10개 교환하고 이동속도 증가 버프
	dlg_menu ( "@90997000", "valentine_event_operation(2)" )		-- 20개 교환하고 공격속도 증가 버프
	dlg_menu ( "@90997001", "valentine_event_operation(3)" )		-- 20개 교환하고 시전속도 증가 버프
	dlg_menu ( "@90997002", "valentine_event_exchange_pet()" )		-- 50개 교환하고 마이 러브하트 팻 지급

	
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end	



-- 발렌타인 이벤트 버프 보상에 대한 함수 
function valentine_event_operation( magic_set )

	-- 하트캔디 개수 얻어오기
	local heartcandy_count = find_item( 2010380 )
	
	-- 버프 3종 받아오기 
	local state_level_1 = get_state_level( 1013 )		-- 이동속도 증가 버프
	local state_level_2 = get_state_level( 1011 )		-- 공격속도 증가 버프
	local state_level_3 = get_state_level( 1012 )		-- 시전 속도 증가 버프
	
		
		-- 하트 캔디 갯수가 10개 미만 일때
		if heartcandy_count < 10 then
			
			if magic_set == 1 then		-- 이동속도 증가 버프
				dlg_title( "@90996995" )
				dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
				
			
			elseif magic_set == 2 then	-- 공격속도 증가 버프
			
				dlg_title( "@90996995" )
				dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
				
			
			elseif magic_set == 3 then	-- 시전속도 증가 버프
				dlg_title( "@90996995" )
				dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
				

			end

		-- 하트 캔디 갯수가 20개 미만일 때
		elseif heartcandy_count < 20 then
			
			if magic_set == 1 then			-- and state_level_1 == 0 이 부분은 해당 버프가 걸려 있지 않다면 정해진 버프를 걸어준다는 조건이다.
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1013, 15, 90000 ) -- 이동속도 증가, lv15, 15분
				delete_item( get_item_handle( 2010380 ), 10 )
				
				
			elseif magic_set == 2 then
				dlg_title( "@90996995" )
				dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
				
				
			elseif magic_set == 3 then
				dlg_title( "@90996995" )
				dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
				
				
			end
			
		-- 하트캔디 갯수가 50개 미만일 때
		elseif heartcandy_count < 50 then
		
			if magic_set == 1 then
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1013, 15, 90000 ) -- 이동속도 증가, lv15, 15분
				delete_item( get_item_handle( 2010380 ), 10 )
				
				
			elseif magic_set == 2 then
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1011, 8, 360000 ) -- 공격속도 증가, lv8, 60분
				delete_item( get_item_handle( 2010380 ), 20 )
				
				
			elseif magic_set == 3 then
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1012, 5, 360000 ) -- 시전속도 증가, lv5, 60분
				delete_item( get_item_handle( 2010380 ), 20 )
				
				
			end
			
		-- 하트캔디 갯수가 50개 이상일 때
		elseif heartcandy_count >= 50 then
		
			if magic_set == 1 then
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1013, 15, 90000 ) -- 이동속도 증가, lv15, 15분
				delete_item( get_item_handle( 2010380 ), 10 )
				
				
			elseif magic_set == 2 then
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1011, 8, 360000 ) -- 공격속도 증가, lv8, 60분
				delete_item( get_item_handle( 2010380 ), 20 )
				
				
			elseif magic_set == 3 then			
				dlg_title( "@90996995" )
				dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
				add_state( 1012, 5, 360000 ) -- 시전속도 증가, lv5, 60분
				delete_item( get_item_handle( 2010380 ), 20 )
				
						
			end
			
			
		else
		--  하트 캔디 개수가 모자랄때
			dlg_title( "@90996995" )	
			dlg_text( "@90997003" )
		
		end
		
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end



-- 발렌타인 이벤트 펫 보상에 대한 함수
function valentine_event_exchange_pet()

	-- 하트캔디 개수 얻어오기
	local heartcandy_count = find_item( 2010380 )
	
	if heartcandy_count >= 50 then
		dlg_title( "@90996995" )
		dlg_text( "@90997004" )			-- 와!! 고마워요. 선물을 드릴께요.
		delete_item( get_item_handle( 2010380 ), 50 )
		insert_item ( 690425, 1 )		-- 러브하트 펫 지급 한다.
		
	else 								-- 50개 이상이 안되는 모든 경우
		dlg_title( "@90996995" )
		dlg_text( "@90997003" )			-- 하트 캔디 개수가 부족하네요.
		
	end
		
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()

end





