-- 몬스터에게서 드랍되는 부활절 음식 재료를 모아 조합하여 음식을 만든 후 음식을 가져 오면 랜덤 박스로 교환해준다.
-- 부활절 빵 : 무기 랜덤 박스
-- 부활절 달걀 : 방어구 랜덤 박스
-- 부활절 스테이크 : 큐브 랜덤 박스
-- 부활절 케이크 : 크리처 랜덤 박스


function NPC_Event_Easter_init()
	cprint( "!빵집 주인 뚜레쥬" )
	set_npc_name(  "@90999200"  )
end


function NPC_Event_Easter_contact()		-- NPC 클릭하면 대화 메뉴 출력된다.

    -- 지역 npc id 가져오기
	local npc_id = get_npc_id()

		-- <이름 출력> 각 npc의 이름을 출력해 준다.
    -- 라크시일때 
    if npc_id == 11030 then
           dlg_title( "@90999201" )
	-- 카탄일때 
	elseif npc_id == 11029 then
	       dlg_title( "@90999201" )
	-- 수련자의섬일때
	elseif npc_id == 11033 then
	       dlg_title( "@90999201" )
	-- 호라이즌일때
	elseif npc_id == 11028 then
	       dlg_title( "@90999201" )
	-- 론도일때
	elseif npc_id == 11031 then
	       dlg_title( "@90999201" )
	-- 도시의 유적일때
	elseif npc_id == 11032 then
	       dlg_title( "@90999201" )
	-- 시크루트일때
	elseif npc_id == 11034 then
	       dlg_title( "@90999201" )		   
	end -- if
	
	dlg_text( "@90999202" )			-- NPC 대사
	

	-- 이벤트 수락
	dlg_menu( "@90999203", "easter_event_agreed()" )

	-- 부활절 음식 교환
	dlg_menu( "@90999204", "easter_event_swap()" )
	
	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()

end

-- 이벤트 수락 
function easter_event_agreed()

	-- 레시피를 받았나 확인
	local item_count = find_item ( 2010400 )
	item_handle = get_item_handle ( 2010400 )
	
	-- 레시피 보상을 받은 적 있는지 체크
	local q_flag0 = tonumber( get_flag( "q20" ) )

	if q_flag0 == nil then
		q_flag0 = 0
		set_flag( "q20", "0" )
	end
			
			-- 보상을 받은 적 있는지 체크
			-- 이미 보상을 받았으면 출력
	
			if q_flag0 >= 1 then
			      dlg_title( "@90999201" )		-- NPC 이름
	
			-- 레시피를 아직 못 받았을 때
			else
				dlg_title( "@90999201" )		-- NPC 이름
				insert_item ( 2010400, 1 )		-- 레시피를 건네 준다.(2010400)
				set_flag( "q20", "1" )
			end
	-- 다이얼로그 출력
	dlg_title( "@90999201" )		--NPC 이름 부활절 이벤트 뚜레쥬
	dlg_text( "@90999205" )			--NPC 대사

	dlg_menu( "@90010003", "NPC_Event_Easter_contact()" )

	-- 대화종료 
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end


