-- 2랭크 전사 아이템 교환 
function christ_event_production_1_1()

	-- 조합 재료 찾기
	local easterbread_count_1 = find_item ( 2010418 )				--판금 조각
	local easterbread_count_2 = find_item ( 2010419 )				--강화 철사

	if easterbread_count_1 >= 2 and easterbread_count_2 >= 5 then

	dlg_title( "@90999214" )										--NPC 이름
	dlg_text( "@90999237" )											--잠시만 기다려 보게.

		insert_item ( 2010434, 1 )									--2랭크 전사 갑옷
		delete_item( get_item_handle( 2010418 ), 2 )				--판금 조각
		delete_item( get_item_handle( 2010419 ), 5 )				--강화 철사

		dlg_menu( "@90010003", "NPC_Event_christ_contact()" )
	
		-- 대화종료 
		dlg_menu( "@90010002", " " )
		dlg_show()


	else

		dlg_title( "@90999214" )									--NPC 이름
		dlg_text( "@90999234" )										--재료 부족


		dlg_menu( "@90010003", "NPC_Event_christ_contact()" )

		-- 대화종료 
		dlg_menu( "@90010002", " " )
		dlg_show()
	end
end	

