function NPC_Event_Lvup_contact()
	local npc_id = get_npc_id()			--지역 npc id 가져오기
		if npc_id == 11037 or 11072 or 11077 or 11082 or 11087 or 11093 then			--라크시 (각 국가별 NPC 자동생성에 따른 NPC ID가 여러개로 분리되어서 각각의 ID를 입력해야 한다.)
			dlg_title( "@90999884" )
		elseif npc_id == 11038 or 11073 or 11078 or 11083 or 11088 or 11094  then		--카탄
			dlg_title( "@90999884" )
		elseif npc_id == 11039 or 11074 or 11079 or 11084 or 11089 or 11095 then		--호라이즌
			dlg_title( "@90999884" )
		elseif npc_id == 11040 or 11075 or 11080 or 11085 or 11090 or 11096 then		--론도
			dlg_title( "@90999884" )
		elseif npc_id == 11041 or 11076 or 11081 or 11086 or 11091 or 11097 then		--도시유적
			dlg_title( "@90999884" )
		end
		-- 다이얼로그 출력
	dlg_title( "@90999884" )          --제목 : 선물대여도우미
	dlg_text( "@90999245" )           --인사말
	-- 대화종료 
	dlg_menu( "@90999246", 'Event_Lvup_present()' )   --선물받기
	dlg_menu( "@90010002", " " )                  --대화종료			
	dlg_show()
end
 		

-- 선물 받기
function Event_Lvup_present()
	
	-- 현재 직업 id를 받아놓는다.
	local job = get_value( "job" )
	-- 레벨 받아옴
	local level = get_value( "level" )
	local q_flag0 = get_flag( "lvup_weapon" )		--무기
	local q_flag1 = get_flag( "lvup_armor" )		--방어
	
	--플레그값 초기화 시켜 주기
		if q_flag0 == "" then
			q_flag0 = 0
		end
		if q_flag1 == "" then
			q_flag1 = 0
		end 
		
	-- 기본 직업은 즐 때림
	if job == 100 or job == 200 or job == 300 then
		-- 다이얼로그 출력
		dlg_title( "@90999884" )        --제목 : 선물대여도우미
		dlg_text( "@90999247" )         --선물을 대여 받으려면 먼저 1차 직업으로 전직을 해야 합니다.
		
		
	elseif level <= 49 then --랭크2무기대여
	
	    --1차 직업을 가지고 있던 2차 직업을 가지고 있던 모두 그에 맞는 아이템을 지급해 준다.
	    if job == 201 or job == 202 or job == 203 or job == 301 or job == 302 or job == 303 or job == 101 or job == 102 or job == 103 or job == 210 or job == 211 or job == 212 or job == 213 or job == 214 or job == 310 or job == 311 or job == 312 or job == 313 or job == 314 or job == 110 or job == 111 or job == 112 or job == 113 or job == 114 then
				
			if q_flag0 >= 1 and q_flag1 >= 1 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목 : 선물대여도우미
				dlg_text( "@90999248" )       --이미 선물을 대여 받으셨네요.
			elseif q_flag0 >= 1 and q_flag1 < 1  then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )       --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010174", 'Event_Lvup_present_armor()' )		--방어구받기
			
			elseif q_flag0 < 1 and q_flag1 >= 1 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )       --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010173", 'Event_Lvup_present_weapon()' )  --무기받기
				
			elseif 	q_flag0 < 1 and q_flag1 < 1 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )		    --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010174", 'Event_Lvup_present_armor()' )   --방어구받기
				dlg_menu( "@90010173", 'Event_Lvup_present_weapon()' )  --무기받기
				
			else
				dlg_title( "오류" )
				dlg_text( "2랭크 대여 처리 조건 오류" )
				
			end
			
		end	
		
		
	elseif level >= 50 and level <= 79 then --랭크3무기대여
	    --1차 직업을 가지고 있던 2차 직업을 가지고 있던 모두 그에 맞는 아이템을 지급해 준다.
	    if job == 201 or job == 202 or job == 203 or job == 301 or job == 302 or job == 303 or job == 101 or job == 102 or job == 103 or job == 210 or job == 211 or job == 212 or job == 213 or job == 214 or job == 310 or job == 311 or job == 312 or job == 313 or job == 314 or job == 110 or job == 111 or job == 112 or job == 113 or job == 114 then
			
			if q_flag0 >= 2 and q_flag1 >= 2 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목 : 선물대여도우미
				dlg_text( "@90999248" )       --이미 선물을 대여 받으셨네요.
			elseif q_flag0 >= 2 and q_flag1 < 2 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )       --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010174", 'Event_Lvup_present_armor()' )		--방어구받기
			
			elseif q_flag0 < 2 and q_flag1 >= 2 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )       --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010173", 'Event_Lvup_present_weapon()' )  --무기받기
			elseif 	q_flag0 < 2 and q_flag1 < 2 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목
				dlg_text( "@90999249" )		    --어떤 선물을 받으시겠습니까?
				dlg_menu( "@90010174", 'Event_Lvup_present_armor()' )   --방어구받기
				dlg_menu( "@90010173", 'Event_Lvup_present_weapon()' )  --무기받기
			end
		end	
	
	
	elseif level >= 80 and level <= 99 then --랭크4무기대여
	    --파이터 등 1차 직업 들은 2차로 전직해라는 문구 출력
	    if job == 201 or job == 202 or job == 203 or job == 301 or job == 302 or job == 303 or job == 101 or job == 102 or job == 103 then
	    dlg_title( "@90999884" )        --제목 : 선물대여도우미
	    dlg_text( "@90993010" )         --2차직업으로 전직해야합니다.
	
		elseif job == 210 or job == 211 or job == 212 or job == 213 or job == 214 or job == 310 or job == 311 or job == 312 or job == 313 or job == 314 or job == 110 or job == 111 or job == 112 or job == 113 or job == 114 then
			if q_flag0 >= 3 and q_flag1 >= 3 then
				-- 다이얼로그 출력
				dlg_title( "@90999884" )      --제목 : 선물대여도우미
				dlg_text( "@90999248" )       --이미 선물을 대여 받으셨네요.
