-- 무기 지급
function Event_Lvup_present_weapon()

		-- 현재 직업 id를 받아놓는다.
		local job = get_value( "job" )
		-- 레벨 받아옴
		local level = get_value( "level" )
	
		--캐릭터 레벨은 낮으나 2차직업을 가진 캐릭터들에 대한 예외처리로
		--2차직업도 검색 조건에 포함시킨다.
	
		if level <= 49 then           --랭크2무기대여
			-- 파이터, 나이트, 워리어 직업 체크
			if 	job == 201 or job == 210 or job == 211 then
				insert_item( 3600094, 1, 10, 10 ) --나이츠소드
				set_flag( "lvup_weapon", "1")	
			
				-- 클레릭, 메이지, 프리스트
				elseif job == 202 or job == 212 or job == 213 then
				insert_item( 3600110, 1, 10, 10 )	--파쇄곤
				set_flag( "lvup_weapon", "1")	
			
				-- 테이머, 브리더
				elseif job == 203 or job == 214 then
				insert_item( 3600110, 1, 10, 10 )	--파쇄곤
				set_flag( "lvup_weapon", "1")
			
				-- 스트라이더, 어쌔신, 레인저
				elseif job == 301 or job == 310 or job == 311 then
				insert_item( 3600094, 1, 10, 10 )	
				insert_item( 3600094, 1, 10, 10 )	--나이츠소드2개대여
				insert_item( 3600102, 1, 10, 10 )	--본크로스보우
				set_flag( "lvup_weapon", "1")	
			
				-- 매지션, 소서러, 다크매지션
				elseif job == 302 or job == 312 or job == 313 then
				insert_item( 3600114, 1, 10, 10 )	--라이프 스틱	
				set_flag( "lvup_weapon", "1")	
			
