function NPC_Event_Japan_summer_contact()
	local npc_id = get_npc_id()			--지역 npc id 가져오기
		if npc_id == 11045 then				--라크시 나츠
			dlg_title( "@90999290" )
			dlg_text( "@90999299" )           --인사말
			
		elseif npc_id == 11046 then			--카탄 야스미
			dlg_title( "@90999292" )
			dlg_text( "@90999299" )           --인사말
			
		elseif npc_id == 11047 then			--호라이즌 스이카
			dlg_title( "@90999294" )
			dlg_text( "@90999299" )           --인사말
			
		elseif npc_id == 11048 then			--론도 우미
			dlg_title( "@90999296" )
			dlg_text( "@90999299" )           --인사말
			
		elseif npc_id == 11057 then			--수련자의 섬 아오이
			dlg_title( "@90999298" )
			dlg_text( "@90999299" )           --인사말
			
		end
			
	-- game.cash_usable_server ? 1: 시크루트 관련 내용 사용 서버  /  0: 사용 안 하는 서버
	if get_env("game.cash_usable_server") == 0 then
		dlg_menu( "@90010013", "open_market( 'flat_sum_NPC_Event_Japan_summer' )" )		--정액제 서버
	else
		dlg_menu( "@90010013", "open_market( 'NPC_Event_Japan_summer' )" )				--부분유료화 서버
	end
	dlg_menu( "@90010002", '' )
 
	dlg_show()
	
end


