			dlg_title( "@90999336" )				-- NPC 이름
			dlg_text( "@90999340" )			-- NPC 대사
			dlg_menu( "@90999342", "summergala_receive_icewater()" )	-- 빙수 받기
			delete_item( get_item_handle( 2010687 ), 1 )		-- 얼음 주머니 삭제
			dlg_menu( "@90010002", " " )	--대화종료
			dlg_show()
	
