	function NPC_Event_Independence_contact()	--NPC를 클릭 하면 메뉴가 출력 된다.
	--<이름 출력> 각 NPC의 이름을 출력 한다.
		if npc_id == 11145 then
		dlg_title( "@90999443" )
		elseif npc_id == 11146 then
		dlg_title( "@90999444" )
		elseif  npc_id == 11147 then
		dlg_title( "@90999445" )
		end
	
		dlg_text( "@90999446" )	--NPC대사

		--NPC 메뉴
		dlg_menu( "@90999449", "Independence_event_receive()" )	--받기
		dlg_menu( "@90010002", "" )	--그만두기
		dlg_show()

	end

	function Independence_event_receive()
	
			local q_flag0 = get_flag( "Independence_item" )
			if q_flag0 == "" then
			q_flag0 = 0
			end
		
		if q_flag0 >= 1 then 
		dlg_text( "@90999448" )	--NPC대사
		dlg_menu( "@90010002", " " )	--그만두기
		dlg_show()
		
		else
		dlg_text( "@90999447" )	--NPC 기본 대사
		insert_item ( 2010731, 1 )			--태극 망토 지급
		set_flag( "Independence_item", "1" )		
		dlg_menu( "@90010002", " " )	--그만두기
		dlg_show()
		end
end


