		--휴면 유저 아이템 대여 이벤트 진행 국가 설정
	
		dlg_title( "@90999555" )
		dlg_text( "@90999556" )
		dlg_menu( "@90999557", "dormancyuser_rental_event_start()" )	--휴면 유저 이벤트 진행
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()
		
	
end

--휴면 유저 이벤트
function dormancyuser_rental_event_start()
	local dormancyuser_rental_event = get_value( "event_code" )	-- 휴면 유저 이벤트 코드

	--flag값 0으로 세팅 하기
	local q_flag1 = get_flag( "rental_weapon" )
	if q_flag1 == nil or q_flag1 == "" then
	set_flag( "rental_weapon", "0" )
	end
	local q_flag2 = get_flag( "rental_armor" )
	if q_flag2 == nil or q_flag2 == "" then
	set_flag( "rental_armor", "0" )
	end

	if dormancyuser_rental_event == 1 then	--event_code 값이 1이면 휴면 유저
		dlg_title( "@90999555" )
		dlg_text( "@90999558" )	--휴면 유저 인경우
		dlg_menu( "@90999560", "dormancyuser_item_rental()" )	--대여 이벤트 아이템 받기
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()
	else
		dlg_title( "@90999555" )
		dlg_text( "@90999562" )	--휴면 유저가 아닌 경우
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()		
	end
end

function dormancyuser_item_rental()
	local job = get_value( "job" )	-- 현재 직업 id를 받아놓는다.
	local level = get_value( "level" )	-- 레벨 받아옴
	local q_flag1 = get_flag( "rental_weapon" )	--무기 플레그 값 받아 오기
	local q_flag2 = get_flag( "rental_armor" )	--방어구 플레그 값 받아 오기

	if job == 100 or job == 200 or job == 300 then
		-- 다이얼로그 출력
		dlg_title( "@90999555" )        --제목 : 선물대여도우미
		dlg_text( "@90999563" )         --선물을 대여 받으려면 먼저 1차 직업으로 전직을 해야 합니다.
	
	elseif level <= 49 then --랭크2무기대여
	    --1차 직업을 가지고 있던 2차 직업을 가지고 있던 모두 그에 맞는 아이템을 지급해 준다.
	    if job == 201 or job == 202 or job == 203 or job == 301 or job == 302 or job == 303 or job == 101 or job == 102 or job == 103 or job == 210 or job == 211 or job == 212 or job == 213 or job == 214 or job == 310 or job == 311 or job == 312 or job == 313 or job == 314 or job == 110 or job == 111 or job == 112 or job == 113 or job == 114 then

			if q_flag1 == 1 and q_flag2 == 1 then
				-- 다이얼로그 출력
				dlg_title( "@90999555" )	--NPC 이름
				dlg_text( "@90999564" )	--무기 및 방어구 둘다 받은 경우
			elseif q_flag1 == 1 then
				-- 다이얼로그 출력
				dlg_title( "@90999555" )	--NPC 이름
				dlg_text( "@90999565" )	--무기를 받은 경우
				dlg_menu( "@90999561", 'dormancyuser_item_armor_receive()' )		--방어구받기
			
			elseif q_flag2 == 1 then
				-- 다이얼로그 출력
