	delete_item( get_item_handle( 2010902 ), 10 )	-- 나뮈르의 껍질 회수
	delete_item( get_item_handle( 2010903 ), 3 )	-- 나뮈르의 씨앗 회수
	
	-- 대화종료 
	dlg_menu( "@90010002", " " )
