	local easterbread_count_1 = find_item ( 2010426 )	--가죽 조각
	local easterbread_count_2 = find_item ( 2010427 )	--가죽 끈
	
	if easterbread_count_1 >= 2 and easterbread_count_2 >= 5 then

		dlg_title( "@90999810" )	--NPC 이름
