		delete_item( get_item_handle( 2010427 ), 10 )	--가죽 끈 삭제
		dlg_menu( "@90010002", " " )	-- 대화종료 
		dlg_show()
	else
		dlg_title( "@90999810" )	--NPC 이름
		dlg_text( "@90999820" )	--재료가 부족하군.
		dlg_menu( "@90010002", " " )	-- 대화종료
		dlg_show()
	end
	
end

