	local easterbread_count_1 = find_item ( 2010430 )	--천 조각
	local easterbread_count_2 = find_item ( 2010431 )	--실
	
	if easterbread_count_1 >= 2 and easterbread_count_2 >= 5 then

		dlg_title( "@90999810" )	--NPC 이름
		dlg_text( "@90999819" )	--자 여기 있네.
		insert_item ( 2011072, 1 )	--파쇄곤 지급
		delete_item( get_item_handle( 2010430 ), 4 )	--천 조각 삭제
		delete_item( get_item_handle( 2010431 ), 10 )	--실 삭제
		dlg_menu( "@90010002", " " )	-- 대화종료 
		dlg_show()
	else
		dlg_title( "@90999810" )	--NPC 이름
		dlg_text( "@90999820" )	--재료가 부족하군.
		dlg_menu( "@90010002", " " )	-- 대화종료
		dlg_show()
	end
	
end

