function NPC_WD_10_spring_event_start()
	local quest_progress01 =  get_quest_progress(3025)
	local quest_progress02 =  get_quest_progress(3024)		
	if quest_progress01 == 255 then
	dlg_title( "@91000118" )
	dlg_text( "@91000145" )
	dlg_menu( "@90010002", "" )
	dlg_show()
	elseif quest_progress02 == 255 then
	dlg_title( "@91000118" )
	dlg_text( "@91000132" )
	dlg_menu( "@90010002", "" )
	dlg_show()
	else
	dlg_title( "@91000118" )
	dlg_text( "@91000119" )
	dlg_menu( "@90010002", "" )
	dlg_show()
	end
end

