--event_code
-- 1이면 휴면 유저, 0이면 일반 유저

function NPC_RU_2010_dormancy_user_event_start()
local dormancyuser_rental_event = get_value( "event_code" )	-- 휴면 유저 이벤트 코드

	if dormancyuser_rental_event == 1 then
		dlg_title( "@90999884" )
		dlg_text( "@91000177" )	--휴면 유저 인경우
		dlg_menu( "@91000178", "RU_2010_dormancy_user_item()" )	--휴면 유저 아이템 받기
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()
	else
		dlg_title( "@90999884" )
		dlg_text( "@91000179" )	--휴면 유저가 아닌 경우
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()		
	end
end

function RU_2010_dormancy_user_item()
local q_flag0 = get_flag( "dormancy_user" )	--아이템 지급 확인
	if q_flag0 == "" then
		q_flag0 = 0
	end

	if q_flag0 < 1 then
	dlg_title( "@90999884" )
	dlg_text( "@91000180" )
	insert_item( 2000203, 10 )	--사랑의 스태미너 세이버
	insert_item( 690416, 1 )	--마이 츄우 15일
	set_flag( "dormancy_user", "1")
