function worldcup_2010_event_1day()

local q_flag1 = get_flag( "soccerball_get" )
	if q_flag1 == "" then
		q_flag1 = 0
	end
	
	if q_flag1 < 1 then
	dlg_title( "@91000466" )
	dlg_text( "@91000467" )
	dlg_menu( "@91000468", "worldcup_2010_event_soccerball_give_1day()" )	--축구공을 받는다.
	dlg_menu( "@91000470", "worldcup_2010_event_soccerball_swap_1()" )	--축구공 교환.
	dlg_menu( "@91000473", "worldcup_2010_event_soccerball_question()" )	--티켓은 어디서 구하나요?
	dlg_menu( "@90010002", "" )	--대화 종료
	dlg_show()
	elseif q_flag1 >= 1 then
	dlg_title( "@91000466" )
	dlg_text( "@91000469" )
	dlg_menu( "@91000470", "worldcup_2010_event_soccerball_swap_1()" )
	dlg_menu( "@91000473", "worldcup_2010_event_soccerball_question()" )
	dlg_menu( "@90010002", " " )	--그만두기
	dlg_show()
	end
end	

