function event_ME_2010_rmadan_armor_2rk_WhiteMail_exchang()
	local enhance
	local handle = get_item_handle( 2012264 )	
	local enhance = get_item_enhance( handle )

	if enhance >= 17 then
		if delete_item( handle, 1 ) == 1 then
			dlg_title( "@91000665")
			dlg_text( "@91000704" )	--NPC 대사(자. 여기 있네.)
			insert_item ( 2012336, 1 )
 			dlg_menu( "@90010002", " " )	--대화종료
			dlg_show()
		else
			dlg_title( "@91000665")
			dlg_text( "@91000681" )	--NPC 대사(착용한 아이템은 바꿔 줄 수가 없다네. 착용을 해제하고 다시 찾아와 주게나.)
			dlg_menu( "@90010002", " " )	--대화종료
			dlg_show()
		end
	else
		dlg_title( "@91000665")
		dlg_text( "@90604910" )	--NPC 대사(인벤토리에 내가 원하는 방어구가 없는것 같은데. 다시 한번 확인해 보게나.)
		dlg_menu( "@90010002", " " )	--대화종료
		dlg_show()
	end
end

