	local current_time = get_os_date( "%Y-%m-%d %H:%M:%S" )
	local current_day = 0
	local local_flag = get_env( "game.local_flag" )

	day1_begin_time = '2011-12-18 11:00:00'	--1day
	day2_begin_time = '2011-12-19 11:00:00'	--2day
