			current_day = 13
		elseif current_time < day14_begin_time then
			current_day = 14
		elseif current_time < day15_begin_time then
			current_day = 15
		elseif current_time < day16_begin_time then
			current_day = 16
		end
	
		if current_day == 1 then
			christmas_2011_event_1day()
		elseif current_day == 2 then
			christmas_2011_event_2day()
