-- 일반 유료 버프 걸기 취소하기
function Event_2011_xmas_event_buff_cancel_operation( magic_set )

		if magic_set == 1 then
			remove_state( 1011, 8 ) -- 공속lv6 취소
		elseif magic_set == 2 then
			remove_state( 1007, 8 ) -- 공격력lv6 취소
		elseif magic_set == 3 then
			remove_state( 1009, 8 ) -- 방어력lv6 취소
		elseif magic_set == 4 then
			remove_state( 1008, 8 ) -- 마력lv6 취소
		elseif magic_set == 5 then
			remove_state( 1010, 8 ) -- 마법방어력lv6 취소
		elseif magic_set == 6 then
			remove_state( 1013, 8 ) -- 이동속도lv6 취소
		else
			remove_state( 1012, 8 ) -- 시전속도lv6 취소

		end
	Event_2011_xmas_event_buff_cancel()
end

