   --============================================================
   --             <<<<<< 텔레포트 작동 (이벤트) >>>>>>
   --============================================================
function RunTeleport_Event( x_pos , y_pos )

	-- 상위 펑션에서 호출한 x, y좌표에 +100을 랜덤값으로 텔레포트함
	warp( x_pos + math.random(0,10) , y_pos + math.random(0,10) )
	
	add_state( 6006, 10, 1000 ) -- 스턴 디버프 10초
	
end
