function NPC_AE_2012_Event_ramadan_c_1day()


local q_flag1 = get_flag( "ramadan_event_c" )
	if q_flag1 == "" then
		q_flag1 = 0
	end

   if q_flag1 < 1 then
   
   
    dlg_title( "@90605322" )	--NPC 이름 (회교도 아브람 <수련자의 섬>)
    dlg_text( "@90605325" )	--대사 (인사)
    dlg_menu( "@90605353", "NPC_ae_2012_event_ramadan_c_menu01()" )	--버프 및 코인 받기 
    dlg_menu( "@90605327", "NPC_ae_2012_event_ramadan_c_menu02()" )	--엔피씨 물어보기
    -- set_flag( "ramadan_event_c", "1" )	
	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
	
	elseif q_flag1 >= 1 then
	
	dlg_title( "@90605322" )
	dlg_text( "@90605351" )
	dlg_menu( "@90605327", "NPC_ae_2012_event_ramadan_c_menu02()" )	--엔피씨 물어보기
	dlg_menu( "@90010002", " " )	--그만두기
