	end

   if q_flag1 < 1 then
   
   
    dlg_title( "@90605323" )	--NPC 이름 (회교도 다쿠안 <수련자의 섬>)
    dlg_text( "@90605325" )	--대사 (인사)
    dlg_menu( "@90605354", "NPC_ae_2012_event_ramadan_d_menu01()" )	--버프 및 코인 받기 
    dlg_menu( "@90605327", "NPC_ae_2012_event_ramadan_d_menu02()" )	--엔피씨 물어보기
