	dlg_show()
	
	elseif q_flag1 >= 1 then
	
	dlg_title( "@90605323" )
	dlg_text( "@90605351" )
	dlg_menu( "@90605327", "NPC_ae_2012_event_ramadan_d_menu02()" )	--엔피씨 물어보기
	dlg_menu( "@90010002", " " )	--그만두기
