function   NPC_2012_Event_species_a_contact()

	
	-- 현재 직업 id를 받아놓는다.
	local job = get_value( "job" )

	if job == 100 or job == 101 or job == 102  or job == 103 or job == 110 or job == 111 or job == 112 or 
	job == 113 or job == 114 or job == 120 or job == 121 or job == 122 or job == 123 or job == 124	then
   species_a_week()
		
    else
	species_a_fail()

end
end


