function    species_a_week()

	local current_time = get_os_date( "%Y-%m-%d %H:%M:%S" )
   -- local current_week = 0
	local local_flag = get_env( "game.local_flag" )
	
	local	week1_end_time = '2013-04-25 12:00:00'	--기본 1주 종료
	local	week2_end_time = '2013-05-02 12:00:00'	--기본 2주 종료
	local	week3_end_time = '2013-05-09 12:00:00'	--기본 3주 종료
	local	week4_end_time = '2013-05-16 12:00:00'	--기본 4주 종료
	
	
	if  local_flag == 1 then	--한국 
		week1_end_time = '2013-04-25 12:00:00'	--1차 종료
		week2_end_time = '2013-05-02 12:00:00'	--2차 종료
		week3_end_time = '2013-05-09 12:00:00'	--3차 종료
		week4_end_time = '2013-05-16 12:00:00'	--4차 종료
		
	elseif local_flag == 2 then -- 홍콩
		
		week1_end_time = '2013-04-25 12:00:00'	--1차 종료
		week2_end_time = '2013-05-02 12:00:00'	--2차 종료
		week3_end_time = '2013-05-09 12:00:00'	--3차 종료
		week4_end_time = '2013-05-16 12:00:00'	--4차 종료

	elseif local_flag == 16 then -- 일본
		
		week1_end_time = '2013-06-20 11:00:00'	--1차 종료
		week2_end_time = '2013-06-27 11:00:00'	--2차 종료
		week3_end_time = '2013-07-04 11:00:00'	--3차 종료
		week4_end_time = '2013-07-11 11:00:00'	--4차 종료		
		
	elseif local_flag == 524288 then -- 인도네시아
		
		week1_end_time = '2013-06-26 11:00:00'	--1차 종료
		week2_end_time = '2013-07-03 11:00:00'	--2차 종료
		week3_end_time = '2013-07-10 11:00:00'	--3차 종료
		week4_end_time = '2013-07-17 11:00:00'	--4차 종료			
		
	elseif local_flag == 8192 then -- 중동
		
		week1_end_time = '2013-07-09 09:00:00'	--1차 종료
		week2_end_time = '2013-07-16 09:00:00'	--2차 종료
		week3_end_time = '2013-07-23 09:00:00'	--3차 종료
		week4_end_time = '2013-07-30 09:00:00'	--4차 종료	


	elseif local_flag ==16384 -- 터키 
			or local_flag ==65536 then -- 이탈리아 
		
		week1_end_time = '2013-07-18 08:00:00'	--1차 종료
		week2_end_time = '2013-07-25 08:00:00'	--2차 종료
		week3_end_time = '2013-08-01 08:00:00'	--3차 종료
		week4_end_time = '2013-08-08 08:00:00'	--4차 종료	

	elseif local_flag ==  4 then --미국
		
		week1_end_time = '2013-07-18 00:00:01'	--1차 종료
		week2_end_time = '2013-07-25 00:00:01'	--2차 종료
		week3_end_time = '2013-08-01 00:00:01'	--3차 종료
		week4_end_time = '2013-08-08 00:00:01'	--4차 종료			
	
	elseif local_flag ==  8 --독일 
			or local_flag ==128 -- 프랑스
			or local_flag ==32768 then  -- 폴란드 
		
		week1_end_time = '2013-07-16 08:00:00'	--1차 종료
		week2_end_time = '2013-07-23 08:00:00'	--2차 종료
		week3_end_time = '2013-07-30 08:00:00'	--3차 종료
		week4_end_time = '2013-08-06 08:00:00'	--4차 종료		
	
	elseif local_flag ==  256 then  -- 러시아 
		
		week1_end_time = '2013-09-16 11:00:00'	--1차 종료
		week2_end_time = '2013-09-23 11:00:00'	--2차 종료
		week3_end_time = '2013-09-30 11:00:00'	--3차 종료
		week4_end_time = '2013-10-07 11:00:00'	--4차 종료		
		
	end
	
	
	
	
	
	
	
	if  current_time < week1_end_time then
	     species_a_week1()
	elseif current_time < week2_end_time then
	     species_a_week2()
	elseif current_time < week3_end_time then 
	     species_a_week3()
		 
	else species_a_week4()	 
	end
		
end
	



