		local dew_a_count = find_item(2012642)	--종족 눈물 확인
		
		if dew_a_count >= 5 then
				
		delete_item( get_item_handle(2012642), 5 )	--종족의 눈물

		local give_dew_a_1_data = get_global_variable( "give_dew_a_1_data" )
		if give_dew_a_1_data == nil or give_dew_a_1_data == "" then
		give_dew_a_1_data = 0
		end				
		
		set_global_variable( "give_dew_a_1_data",  give_dew_a_1_data+5  )

		dlg_text( "@90605369\v#@give_dew_a_1_data@#\v" .. give_dew_a_1_data+5 )	--대사		
		
		dlg_menu( "@90010003", "NPC_2012_Event_species_a_contact()" )		--처음으로				
		dlg_menu( "@90010002", "" )	--대화 종료
		dlg_show()
		
		else
		dlg_title( "@90605360" )
		dlg_text( "@90605370" )	--개수 모자름
		dlg_menu( "@90010003", "NPC_2012_Event_species_a_contact()" )		--처음으로		
			--npc 기본 메뉴
		dlg_menu( "@90010002", "")--그만두기
		dlg_show()
		
		end
		
	end






