	function species_a_week1_check_give()
	

		
		local give_dew_a_1_data = get_global_variable( "give_dew_a_1_data" )
		local give_dew_b_1_data = get_global_variable( "give_dew_b_1_data" )
		local give_dew_c_1_data = get_global_variable( "give_dew_c_1_data" )
		
		
		
		
		if give_dew_a_1_data == nil or give_dew_a_1_data == "" then
		give_dew_a_1_data = 0
		end
		if give_dew_b_1_data == nil or give_dew_b_1_data == "" then
		give_dew_b_1_data = 0
		end
		
		if give_dew_c_1_data == nil or give_dew_c_1_data == "" then
		give_dew_c_1_data = 0
		end
	
		dlg_title( "@90605360" )
		dlg_text(sconv("@90605493" , "#@give_dew_a_1_data@#" , give_dew_a_1_data , "#@give_dew_b_1_data@#" , tostring(give_dew_b_1_data), "#@give_dew_c_1_data@#" , tostring(give_dew_c_1_data)))
		dlg_menu( "@90010003", "NPC_2012_Event_species_a_contact()" )	--처음으로
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()
	end


