		dlg_menu( "@90605365", "species_a_week2_give1()" )	--1개 기부
		dlg_menu( "@90605366", "species_a_week2_give5()" )	--5개 기부
		dlg_menu( "@90605367", "species_a_week2_give10()" )	--10개 기부
		dlg_menu( "@90605368", "species_a_week2_check_give()" )	--종족 눈물 개수 확인
		
