end
	
	
function   species_a_week2_buff()

		local give_dew_a_1_data = get_global_variable( "give_dew_a_1_data" )
		if give_dew_a_1_data == nil or give_dew_a_1_data == "" then
		give_dew_a_1_data = 0
		end				
		local give_dew_b_1_data = get_global_variable( "give_dew_b_1_data" )
		if give_dew_b_1_data == nil or give_dew_b_1_data == "" then
		give_dew_b_1_data = 0
		end				
		
		local give_dew_c_1_data = get_global_variable( "give_dew_c_1_data" )
		if give_dew_c_1_data == nil or give_dew_c_1_data == "" then
		give_dew_c_1_data = 0
		end
		
	
	dlg_title( "@90605360" )	--npc이름		
	
	local specise_ring1 = find_item(2902172)	--1등선물 확인 
	local specise_ring2 = find_item(2902173)	--2등선물 확인 	
	
	if specise_ring1 == nil or specise_ring1 == "" then
		specise_ring1 = 0
	end
	
	if specise_ring2 == nil or specise_ring2 == "" then
		specise_ring2 = 0
	end

		if specise_ring1 == 0 and specise_ring2 == 0 then
		if give_dew_a_1_data >= give_dew_b_1_data  and  give_dew_a_1_data >= give_dew_c_1_data then
			insert_item(2902172,1)   ---신규 제작 이벤트 아이템 1등
			dlg_text( "@90605372" )	--1등 대사
		elseif give_dew_a_1_data >= give_dew_b_1_data  or  give_dew_a_1_data >= give_dew_c_1_data then
			insert_item(2902173,1)   ---신규 제작 이벤트 아이템 2등 
			dlg_text( "@90605791" )	--2등 대사 	
		else 
			local q_flag = get_flag("species_3rd_2")
			if q_flag == nil or q_flag == "" then
				q_flag = 0
			end
			
			if q_flag == 0 then 
				set_flag("species_3rd_2",1)
				dlg_text( "@90605792" )	--꼴찌 대사 	
				insert_item(2010454,1)   ---꼴찌 
				insert_item(2012834,1)   ---꼴찌 			
			else  	dlg_text( "@90605793" )	--선물 받은 대사.
			
			end
			
		end
	else
 	dlg_text( "@90605793" )	--선물 받은 대사.
	end
	
	
	    --npc 기본 메뉴
		dlg_menu( "@90010003", " NPC_2012_Event_species_a_contact()" )	--돌아가기
		dlg_menu( "@90010002", " " )	--그만두기
		dlg_show()

end
	
	
	
	
