	if  local_flag == 1 then	--한국 
		week1_end_time = '2013-04-25 12:00:00'	--1차 종료
		week2_end_time = '2013-05-02 12:00:00'	--2차 종료
		week3_end_time = '2013-05-09 12:00:00'	--3차 종료
		week4_end_time = '2013-05-16 12:00:00'	--4차 종료
		
	elseif local_flag == 2 then -- 홍콩
		
		week1_end_time = '2013-04-25 12:00:00'	--1차 종료
		week2_end_time = '2013-05-02 12:00:00'	--2차 종료
		week3_end_time = '2013-05-09 12:00:00'	--3차 종료
		week4_end_time = '2013-05-16 12:00:00'	--4차 종료
		
	elseif local_flag == 16 then -- 일본
		
