		week2_end_time = '2013-06-27 11:00:00'	--2차 종료
		week3_end_time = '2013-07-04 11:00:00'	--3차 종료
		week4_end_time = '2013-07-11 11:00:00'	--4차 종료		
		
	elseif local_flag == 524288 then -- 인도네시아
		
		week1_end_time = '2013-06-26 11:00:00'	--1차 종료
		week2_end_time = '2013-07-03 11:00:00'	--2차 종료
		week3_end_time = '2013-07-10 11:00:00'	--3차 종료
		week4_end_time = '2013-07-17 11:00:00'	--4차 종료			
		
	elseif local_flag == 8192 then -- 중동
		
