		week2_end_time = '2013-07-16 09:00:00'	--2차 종료
		week3_end_time = '2013-07-23 09:00:00'	--3차 종료
		week4_end_time = '2013-07-30 09:00:00'	--4차 종료	


	elseif local_flag ==16384 -- 터키 
			or local_flag ==65536 then -- 이탈리아 
		
		week1_end_time = '2013-07-18 08:00:00'	--1차 종료
		week2_end_time = '2013-07-25 08:00:00'	--2차 종료
		week3_end_time = '2013-08-01 08:00:00'	--3차 종료
		week4_end_time = '2013-08-08 08:00:00'	--4차 종료	

	elseif local_flag ==  4 then --미국
		
		week1_end_time = '2013-07-18 00:00:01'	--1차 종료
		week2_end_time = '2013-07-25 00:00:01'	--2차 종료
		week3_end_time = '2013-08-01 00:00:01'	--3차 종료
		week4_end_time = '2013-08-08 00:00:01'	--4차 종료			
		
	elseif local_flag ==  8 --독일 
			or local_flag ==128 -- 프랑스
			or local_flag ==32768 then -- 폴란드 
		
