	local specise_ring2 = find_item(2902173)	--2등선물 확인 	
	
	if specise_ring1 == nil or specise_ring1 == "" then
		specise_ring1 = 0
	end
	
	if specise_ring2 == nil or specise_ring2 == "" then
		specise_ring2 = 0
	end

