function NPC_all_2012_EnchantEvent_enhance()
		
	local i, handle, lv, enhance, code  
	
	-- 무기 아이템 핸들 얻어옴
	
	dlg_title( "@90605504" )	--npc이름		
	dlg_text( "@90605549" )		--npc 기본 대사
				
	for i = 0, 1 do
	
		handle = get_wear_item_handle( i )
		--cprint ( sconv( handle) )
		
		if handle ~= 0 then
	 
			lv = get_item_level( handle )
			enhance =  get_item_enhance( handle )
			
			--이벤트 무기류인지 검사하기 위해 아이템 코드 얻어옴
			code = get_item_code( handle ) 
			--cprint ( sconv( handle, code ) )
			
			if not( code < 2012665 or ( code > 2012724 and code < 2012749 ) or code > 2012760 ) then 
		
				if lv == 0 then
					set_item_level( handle , 1 )
				end
				
				-- ## 시작
				-- 해당 아이템의 강화단계, 아이템명, Lv을 텍스트로 구성
				if enhance ~= 0 then
					-- 강화되어있으면 +x 표시
					text = sconv("@90010010", "#@enhance_level@#",tostring(enhance) ,"#@item_name@#", "@" .. tostring( get_item_name_id( get_item_code( handle ) ) ) , "#@item_Lv@#",tostring(lv))
					-- ## 끝 @90010010 = + #@enhance_level@# #@item_name@# Lv #@item_Lv@#	

				else
					text = sconv("@90010011", "#@item_name@#", "@" .. tostring( get_item_name_id( get_item_code( handle ) ) ), "#@item_Lv@#",tostring(lv))
						-- ## 끝 @90010011 = #@item_name@# Lv #@item_Lv@#
				end
					-- 아이템 레벨업 스크립트 펑션을 메뉴에 추가
				
				
				
				dlg_menu( text, 'event_enhance_check( '..handle..' )')				--강화 아이템 선택
				
			end
			
		end
		
	end
	dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )		--돌아가기
	dlg_show()

end

function event_enhance_check( handle )
	
	local max_level, rank, itemcode, enhance

	rank = get_item_rank( handle )	

	--강화석 아이템 아이디가 2012646 ~ 2012651 인것을 감안해서 랭크에 더해주어서 아이템 코드 계산하는 방법
	itemcode = rank + 2012644
	
	max_level = 20
	
	enhance =  get_item_enhance( handle )
	
	if enhance >= max_level then

		--업글 가능한 레벨을 벗어나므로 무효        
		dlg_title( "@90605504" )
		dlg_text( "@90605550" )
		
		--돌아가기
		dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )	
		dlg_show()
			
		return
	end
	
	if has_item( itemcode ) >= 1 then 

		--강화하시겠습니까 
		dlg_title( "@90605504" )
		dlg_text( "@90605551" )
		
		--예 아니오
		dlg_menu( "@90010195", 'NPC_all_2012_EnchantEvent_enhance_up( ' ..handle.. '  )' )		-- 강화함수 진행. 
		dlg_menu( "@90010196", 'NPC_all_2012_EnchantEvent_b ()' )								-- 선택 메뉴로 돌아가기.
		dlg_show()
	
	else
		--강화석 없을 시 대사
		dlg_title( "@90605504" )
		dlg_text( "@90605552" )
		
		--예 아니오
		dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )								-- 선택 메뉴로 돌아가기.
		dlg_show()
		
	end
end

function NPC_all_2012_EnchantEvent_enhance_up( handle )
	
	local enhance_table = { 90, 90, 90, 90, 90, 80, 80, 80, 80, 80, 70, 70, 70, 70, 70, 60, 60, 60, 60, 60, 50, 50, 50, 50, 50 }
	local lv = get_item_level( handle )
	local code = get_item_code( handle )
	
	if not( code < 2012665 or ( code > 2012724 and code < 2012749 ) or code > 2012760 ) then 
	
		local enhance = get_item_enhance( handle )
		
		rank = get_item_rank( handle )	
		--강화석 아이템 아이디가 2012646 ~ 2012651 인것을 감안해서 랭크에 더해주어서 아이템 코드 계산하는 방법
		itemcode = rank + 2012644
		
		local enchant_stone_handle = get_item_handle( itemcode )
		
		if enchant_stone_handle == 0 then
			--강화석 없어서 안되는 대사
			dlg_title( "@90605504" )
			dlg_text( "@90605552" )
			
			--돌아가기
			dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )	
			dlg_show()
		
			return
		end
		
		if enhance >= 20 then

		--업글 가능한 레벨을 벗어나므로 무효        
		dlg_title( "@90605504" )
		dlg_text( "@90605550" )
		
		--돌아가기
		dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )	
		dlg_show()
			
		return
	end
	
		success = is_erasable_item( enchant_stone_handle ) and delete_item( enchant_stone_handle, 1 )

		if success == 1 then
			if ( math.random( 1, 100 ) <= enhance_table[ enhance + 1 ] ) then
				set_item_enhance( handle , enhance + 1 )
				
				-- 강화가 성공하였으니 enhance 재조사
				enhance = get_item_enhance( handle )
				
				--강화 성공
				dlg_title( "@90605504" )
				dlg_text( "@90605553" )
				
				if enhance ~= 0 then
					-- 강화되어있으면 +x 표시
					text = sconv("@90010010", "#@enhance_level@#",tostring(enhance) ,"#@item_name@#", "@" .. tostring( get_item_name_id( get_item_code( handle ) ) ) , "#@item_Lv@#",tostring(lv))
					-- ## 끝 @90010010 = + #@enhance_level@# #@item_name@# Lv #@item_Lv@#	

				else
					text = sconv("@90010011", "#@item_name@#", "@" .. tostring( get_item_name_id( get_item_code( handle ) ) ), "#@item_Lv@#",tostring(lv))
						-- ## 끝 @90010011 = #@item_name@# Lv #@item_Lv@#
				end
				
				dlg_menu( text, 'NPC_all_2012_EnchantEvent_enhance_up( '..handle..' )')
				
			else
				set_item_enhance( handle, 0 )
			
				--강화 실패
				dlg_title( "@90605504" )
				dlg_text( "@90605554" )
			end
		end

		--돌아가기
		dlg_menu( "@90010003", 'NPC_all_2012_EnchantEvent_b ()' )
		dlg_show()
	end
end

