function NPC_event_2013_EnchantEvent_b()

	dlg_title("@90605803")
	dlg_text("@90605821")


	
	dlg_menu( "@90605834", "NPC_event_2013_EnchantEvent_b_enhance()" )	--강화 하기
	
	--npc 기본 메뉴
	dlg_menu( "@90010002", " " )	--그만두기
	dlg_show()
	

end

function NPC_event_2013_EnchantEvent_b_enhance()
	local enhance_gold = {90000,180000,360000,640000,1280000,1280000,13888000,13888000,13888000,33888000,50888000,100888000,223788800,323788800,323788800}
	
	local i, handle, lv, enhance, code  
	
	-- 무기 아이템 핸들 얻어옴
	
	dlg_title( "@90605803" )	--npc이름		
	dlg_text( "@90605849" )		--npc 기본 대사
				
	for i = 0, 1 do
	
		handle = get_wear_item_handle( i )
		--cprint ( sconv( handle) )
		
		if handle ~= 0 then
	 
			enhance =  get_item_enhance( handle )

			--이벤트 무기류인지 검사하기 위해 아이템 코드 얻어옴
			code = get_item_code( handle ) 
			--cprint ( sconv( handle, code ) )
			
			if code == 2902174 then 
		
	--			if enhance < 15 then
	--				set_item_level( handle , enhance + 1 )
	--			end
				
				-- ## 시작
				-- 해당 아이템의 강화단계, 아이템명, Lv을 텍스트로 구성
				if enhance >=1    and   enhance < 15 then
					-- 강화되어있으면 +x 표시
					text = sconv("@90605845", "#@enhance_level@#",tostring(enhance) ,"#@enhance_gold@#",tostring(enhance_gold[ enhance + 1 ]))
					-- ## 끝 @90010010 = + #@enhance_level@# #@item_name@# Lv #@item_Lv@#	
					
					
				elseif enhance == 15 then 
				dlg_title( "@90605803" )	--npc이름
				dlg_text( "@90605843" )
				dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b ()' )	
				dlg_menu( "@90010002", " " )	--그만두기
				dlg_show()
				
				else
					text = sconv("@90605846", "#@enhance_gold@#",tostring(enhance_gold[ enhance + 1 ]))
						-- ## 끝 @90010011 = #@item_name@# Lv #@item_Lv@#
				end
					-- 아이템 레벨업 스크립트 펑션을 메뉴에 추가
				
				
				
				dlg_menu( text, 'NPC_event_2013_EnchantEvent_b_enhance_select( '..handle..' )')				--강화 아이템 선택
			
			return
						
			end
		
		
		else 
			dlg_title("@90605803")
			dlg_text( "@90605849" )
			dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b ()' )	
			dlg_menu( "@90010002", " " )	--그만두기
			dlg_show()

		
		end
		
	end
	dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b_enhance ()' )		--돌아가기
	dlg_menu( "@90010002", " " )	--그만두기
	dlg_show()

end

function NPC_event_2013_EnchantEvent_b_enhance_select( handle )
	local max_level, itemcode, enhance
	local gold = get_value( "gold" )
	max_level = 15
	
	enhance =  get_item_enhance( handle )
	
	if enhance >= max_level then
		--업글 가능한 레벨을 벗어나므로 무효        
		dlg_title( "@90605803" )
		dlg_text( "@90605843" )
		
		--돌아가기
		dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b_enhance ()' )	
		dlg_menu( "@90010002", " " )	--그만두기
		dlg_show()
	else
		local enhance_gold = {90000,180000,360000,640000,1280000,1280000,13888000,13888000,13888000,33888000,50888000,100888000,223788800,323788800,323788800}
		if gold < enhance_gold[enhance + 1] then
			--루피가 없을때
			dlg_title( "@90605803" )
			dlg_text( "@90605847" )
			dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b_enhance ()' )	
			dlg_menu( "@90010002", " " )	--그만두기
			dlg_show()
			
		else

		--강화하시겠습니까 
		dlg_title( "@90605803" )
		dlg_text( "@90605551" )
		
		--예 아니오
		dlg_menu( "@90010195", 'NPC_event_2013_EnchantEvent_b_enhance_up( ' ..handle.. '  )' )		-- 강화함수 진행. 
		dlg_menu( "@90010196", 'NPC_event_2013_EnchantEvent_b_enhance ()' )								-- 선택 메뉴로 돌아가기.

		dlg_show()
		end
	end
end

function NPC_event_2013_EnchantEvent_b_enhance_up( handle )
	local enhance_table = { 90, 90, 90, 80, 80, 80, 70, 70, 70, 60, 60, 60, 51, 51, 51}
	local code = get_item_code( handle )
	local max_level = 15
	local gold = get_value( "gold" )
		
	if code == 2902174 then 
		
		local enhance = get_item_enhance( handle )
		
		if enhance >= max_level then
			--업글 가능한 레벨을 벗어나므로 무효        
			dlg_title( "@90605803" )
			dlg_text( "@90605843" )

			--돌아가기
			dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b_enhance ()' )	
			dlg_menu( "@90010002", " " )	--그만두기
			dlg_show()
		else
			local enhance_gold = {90000,180000,360000,640000,1280000,1280000,13888000,13888000,13888000,33888000,50888000,100888000,223788800,323788800,323788800}
			if gold < enhance_gold[ enhance + 1 ] then
				--루피가 없을때
				dlg_title( "@90605803" )
				dlg_text( "@90605847" )
				dlg_menu( "@90010002", " " )	--그만두기
				dlg_show()

				return
			end

			if ( math.random( 1, 100 ) <= enhance_table[ enhance + 1 ] ) then
				local success = set_item_enhance( handle , enhance + 1 )
				if success then
					set_value( "gold", get_value( "gold" ) - enhance_gold[ enhance + 1 ] )
				end
				
				-- 강화가 성공하였으니 enhance 재조사
				enhance = get_item_enhance( handle )
					if enhance == 15 then 
						NPC_event_2013_EnchantEvent_b_enhance_select( handle )
						return
					end
				
				
				--강화 성공
				dlg_title( "@90605803" )
				dlg_text( "@90605553" )
				
				-- 강화되어있으면 +x 표시
				text = sconv("@90605845", "#@enhance_level@#",tostring(enhance) ,"#@item_name@#", "@" .. tostring( get_item_name_id( get_item_code( handle ) ) ), "#@enhance_gold@#",tostring(enhance_gold[ enhance + 1 ]))
				-- ## 끝 @90605845 = + #@enhance_level@# #@item_name@# 

				dlg_menu( text, 'NPC_event_2013_EnchantEvent_b_enhance_up( '..handle..' )')
			else
				set_item_enhance_fail(handle)
				set_value( "gold", get_value( "gold" ) - enhance_gold[ enhance + 1 ] )
				--강화 실패
				dlg_title( "@90605803" )
				dlg_text( "@90605848" )
			end
		end

		--돌아가기
		dlg_menu( "@90010003", 'NPC_event_2013_EnchantEvent_b_enhance ()' )
		dlg_show()
	end
end



