-- 탐욕의 조각( 이벤트 몬스터 ) 사망 시 스크립트
function Pluto_event_monster_death( monster_handle ) 

	local monster_id = get_monster_id( monster_handle )
	
	if monster_id ==  1100054 then
		cast_world_state( 41102522, 1, 60000 )		
	elseif monster_id ==  1100055 then
		cast_world_state( 41102523, 1, 60000 )		
	elseif monster_id ==  1100056 then
		cast_world_state( 41102524, 1, 60000 )		
	elseif monster_id ==  1100057 then
		cast_world_state( 41102525, 1, 60000 )		
	end
end

-- NPC 클릭 시 스크립트

function NPC_Event_Pluto_contact()

	local npc_id = get_npc_id()

	if npc_id == 11886 then
	
		dlg_title( "@90605878" )          
		  
	elseif npc_id == 11887 then
	
		dlg_title( "@90605879" )          
	     
	elseif npc_id == 11888 then
	
		dlg_title( "@90605880" )          

	elseif npc_id == 11889 then
	
		dlg_title( "@90605881" )          
	
	end
	
	dlg_text( "@90605883" )   -- 인사말     
	dlg_menu( "@690000094", " NPC_Event_Pluto_menu_index01() " )   
	dlg_menu( "@690000114", " NPC_Event_Pluto_menu_index02() " )   
	dlg_menu( "@690000115", " NPC_Event_Pluto_menu_index03() " )   
	dlg_menu( "@690000116", " NPC_Event_Pluto_menu_index04() " )    
	dlg_menu( "@90010002", " " )   
	dlg_show()

end

