function NPC_Event_Pluto_menu_index01_01()
	local npc_id = get_npc_id()	
	local item_code = 0
	local reward_code = 0
	if npc_id == 11886 then
		dlg_title( "@90605878" )
		item_code = 601100319
		reward_code = 601100330
	elseif npc_id == 11887 then
		dlg_title( "@90605879" )
		item_code = 601100320
		reward_code = 601100331
	elseif npc_id == 11888 then
		dlg_title( "@90605880" )
		item_code = 601100321
		reward_code = 601100332
	elseif npc_id == 11889 then
		dlg_title( "@90605881" )
		item_code = 601100322
		reward_code = 601100333
	end
		
	local item_count = find_item ( item_code )
	if item_count >= 15 then
		dlg_text( "@90605892" )   -- 교환완료
		delete_item( get_item_handle( item_code ), 15 )
		insert_item( reward_code, 1 )
	else
		dlg_text( "@90605885" )   -- 부족해
	end
	
	dlg_menu( "@9514", "NPC_Event_Pluto_contact()" ) 
	dlg_menu( "@90010002", " " )   
	dlg_show()
	
end

