function NPC_Event_Pluto_menu_index04() --각 지역의 탐욕의 조각이 죽으면서 걸어준 버프가 걸려있을 경우 플루토 동전 받기

	local npc_id = get_npc_id()
	local state_code
	local state_level
	local reward_code
	if npc_id == 11886 then
		state_code = 41102522
		reward_code = 601100319
		dlg_title( "@90605878" )
	elseif npc_id == 11887 then
		state_code = 41102523
		reward_code = 601100320
		dlg_title( "@90605879" )
	elseif npc_id == 11888 then
		state_code = 41102524
		reward_code = 601100321
		dlg_title( "@90605880" )
	elseif npc_id == 11889 then
		state_code = 41102525
		reward_code = 601100322
		dlg_title( "@90605881" )
	end
	
	local state_level = get_state_level (state_code)
	
	if state_level == 1 then  --버프가 걸려있고 
		dlg_text( "@90605889" )
		insert_item( reward_code, 10 )	-- 플루토 동전을 준다
		remove_state( state_code, 231 )
		
	elseif state_level == 0 then --버프가 걸려있고 
		dlg_text( "@90605891" )
	else 
		dlg_text( "@90605890" )
	end
	
	dlg_menu( "@9514", "NPC_Event_Pluto_contact()" ) 
	dlg_menu( "@90010002", " " )   
	dlg_show()
	
end


