function NPC_2013_christmas_event_change_gift(num) -- 메뉴3-1, 3-2의 교환 로직

	dlg_title( "@90605896" )

	local gift_item_code
	local need_ticket
	
	if num == 1 then
		gift_item_code = 2902210 -- 한손 장검
		need_ticket = 9
	elseif num == 2 then
		gift_item_code = 2902211 -- 양손 장검
		need_ticket = 18
	elseif num == 3 then
		gift_item_code = 2902212 -- 단검
		need_ticket = 9
	elseif num == 4 then
		gift_item_code = 2902213 -- 양손 창
		need_ticket = 18
	elseif num == 5 then
		gift_item_code = 2902221 -- 한손 도끼
		need_ticket = 9
	elseif num == 6 then
		gift_item_code = 2902214 -- 양손 도끼
		need_ticket = 18
	elseif num == 7 then
		gift_item_code = 2902215 -- 한손 메이스
		need_ticket = 9
	elseif num == 8 then
		gift_item_code = 2902216 -- 양손 메이스
		need_ticket = 18
	elseif num == 9 then
		gift_item_code = 2902217 -- 대궁
		need_ticket = 18
	elseif num == 10 then
		gift_item_code = 2902218 -- 석궁
		need_ticket = 18
	elseif num == 11 then
		gift_item_code = 2902219 -- 한손 지팡이
		need_ticket = 9
