	-- 보상을 받을 자격 검증
	local current_date = get_os_date( "%Y-%m-%d" )
	local christmas_last_login_date = get_flag( "2014_christmas_last_login_date" )
	
	if christmas_last_login_date ~= current_date then
		if christmas_last_login_date == nil or christmas_last_login_date == "" or christmas_last_login_date == yesterday[current_date] then
			-- 보상을 받을 기준이 될 값들을 저장한다
			set_flag( "2014_christmas_toy_count_yesterday", get_flag( "2014_christmas_toy_count" ) or "0" )
		else
			set_flag( "2014_christmas_toy_count_yesterday", "0" )
		end

		set_flag( "2014_christmas_team_yesterday", get_flag( "2014_christmas_team" ) )
		set_flag( "2014_christmas_toy_count", "0" )
		set_flag( "2014_christmas_last_login_date", current_date )
	end
end

function is_winning_team()
	local christmas_team = get_flag( "2014_christmas_team_yesterday" )
	local christmas_winning_team = tostring( get_global_variable( "2014_christmas_winning_team" ) ) or ""
	local length = #christmas_winning_team
	christmas_winning_team = tonumber( christmas_winning_team )

	for i = 1, length do
		local c = christmas_winning_team % 10
		christmas_winning_team = math.floor( christmas_winning_team / 10 )
		if christmas_team == c then
			return true
		end
	end

	return false
end

function is_final_winning_team()
	local christmas_team = get_flag( "2014_christmas_team_yesterday" )
	local christmas_winning_team = tostring( get_global_variable( "2014_christmas_final_winning_team" ) ) or ""
	local length = #christmas_winning_team
	christmas_winning_team = tonumber( christmas_winning_team )

	for i = 1, length do
		local c = christmas_winning_team % 10
		christmas_winning_team = math.floor( christmas_winning_team / 10 )
		if christmas_team == c then
			return true
		end
	end

	return false
end

function is_last_day()
	local state_code = get_local_info()
	local current_date = get_os_date( "%Y-%m-%d" )

	-- 이벤트 시간 설정(최종 보상 획득 기간, 기존 일정에 하루를 더해 계산)
	if state_code == 1 then -- 한국
		christmas_2014_event_last_day = '2015-01-01'
	elseif state_code == 16 then -- 일본
		christmas_2014_event_last_day = '2015-01-07'
	elseif state_code == 512 then -- 동남아 수정
		christmas_2014_event_last_day = '2015-01-03'
	elseif state_code == 4 or state_code == 8 or state_code == 128 or state_code == 16384 or state_code == 32768 or state_code == 65536 then -- 미국, 유럽
		christmas_2014_event_last_day = '2014-12-31'
	elseif state_code == 256 then -- 러시아 추가
		christmas_2014_event_last_day = '2015-01-13'
	elseif state_code == 8192 then -- 중동 라이브 추가
		christmas_2014_event_last_day = '2015-01-28'
	end
	
	return current_date == christmas_2014_event_last_day
end

function is_mvp()
	local christmas_team = get_flag( "2014_christmas_team_yesterday" )
	local christmas_team_mvp_toy_count_yesterday = tonumber( get_global_variable( "2014_christmas_team_mvp_toy_count_yesterday_" .. christmas_team ) ) or 0
	if christmas_team_mvp_toy_count_yesterday < 30 then
		return false
	end

	local christmas_toy_count_yesterday = get_flag( "2014_christmas_toy_count_yesterday" )
	return christmas_toy_count_yesterday == christmas_team_mvp_toy_count_yesterday
end]]

