function NPC_Event_2014_halloween_trade_give(deleted_item_count)
	local item_count = find_item ( 2013535 ) ------------------------------------- 좀비 치료약
	if deleted_item_count == 0 then
		deleted_item_count = item_count
	end

	local halloween_2014_give = get_flag( "halloween_2014_give" )			 --- npc에게 준 횟수
	local halloween_2014_title = get_flag( "halloween_2014_title" ) 		 --- 타이틀 획득한 적이 있는지 확인
	local halloween_2014_buff = get_global_variable( "halloween_2014_buff" ) --- 월드 버프용 전체 치료약 받은 횟수
	if halloween_2014_buff == nil or halloween_2014_buff == "" then -------- 전체 좀비 치료약 받은 개수가 없을 경우
		halloween_2014_buff = 0
	end

	if halloween_2014_give == nil or halloween_2014_give == "" then ---------- 좀비 치료약을 건네준 적이 없는 경우
		halloween_2014_give = 0
	end

	if halloween_2014_title == nil or halloween_2014_title == "" then -------- 2014 할로윈 타이틀을 얻지 않은 경우
		halloween_2014_title = 0
	end

	if deleted_item_count > 0 and item_count >= deleted_item_count then

		dlg_title( "@90606313" )	--NPC 이름(마녀 의사)
		dlg_text( "@90606325" )		--기부하기 선택 시 대사 (기본)
		delete_item( get_item_handle( 2013535 ), deleted_item_count )
		set_flag( "halloween_2014_give", halloween_2014_give+deleted_item_count )
		set_global_variable( "halloween_2014_buff", halloween_2014_buff+deleted_item_count )
		dlg_menu( "@90010003", 'NPC_Event_2014_halloween_contact()' )   --돌아가기
		dlg_menu( "@90010002", " " )	--대화 종료
		dlg_show()

		halloween_2014_give = halloween_2014_give + deleted_item_count
		local old_halloween_2014_buff = halloween_2014_buff
		halloween_2014_buff = halloween_2014_buff + deleted_item_count

		if halloween_2014_title == 0 and halloween_2014_give >= 3 then
			NPC_Event_2014_halloween_trade_title()
		end

		if math.floor(old_halloween_2014_buff / 100) ~= math.floor(halloween_2014_buff / 100) then
			NPC_Event_2014_halloween_trade_buff(math.floor(halloween_2014_buff / 100))
		end
	else 
		NPC_Event_2014_halloween_fail()
	end
	
end

function NPC_Event_2014_halloween_fail()

	dlg_title( "@90606313" )	--NPC 이름(마녀 의사)
	dlg_text( "@90606326" )		--npc 기본 대사
	
	dlg_menu( "@90010003", 'NPC_Event_2014_halloween_contact()' ) 	--돌아가기
	dlg_show()

end

function NPC_Event_2014_halloween_trade_title()

	dlg_title( "@90606313" )	--NPC 이름(마녀 의사)
	dlg_text( "@90606331" )		--npc 기본 대사

	achieve_title(246)
	set_flag( "halloween_2014_title", 1 ) -- 타이틀 얻고 난 뒤 타이틀 획득 표시

	--npc 기본 메뉴
	dlg_menu( "@90010002", " " )
	dlg_show()

end

function NPC_Event_2014_halloween_trade_buff(level)

	if level > 5 then
		return
	end

	dlg_title( "@90606313" )	--NPC 이름(마녀 의사)
	dlg_text( "@90606331" )		--npc 기본 대사

	remove_event_state( 145012, 500 )	-- 월드 버프 제거
	add_event_state( 145012, level )	-- 월드 버프 발동

	--npc 기본 메뉴
	dlg_menu( "@90010002", " " )
	dlg_show()
	
end ]]


