--[[2014 크리스마스  이벤트
--==================================================================================================================
function NPC_Event_2014_christmas_pixie( team, title, text )
	dlg_title( title ) -- 심술쟁이 요정

	local christmas_team = get_flag( "2014_christmas_team" )
	if team == christmas_team then
		set_reward()
		set_daily()

		local christmas_team_yesterday = get_flag( "2014_christmas_team_yesterday" )
		local christmas_toy_count_yesterday = tonumber( get_flag( "2014_christmas_toy_count_yesterday" ) ) or 0

		if christmas_toy_count_yesterday > 0 then
			if christmas_toy_count_yesterday >= 5 then
				insert_item( 2013548, 1 )
				text = "@90606348"
			end

			if is_winning_team() == true then
				local christmas_team_mvp_toy_count_yesterday = tonumber( get_global_variable( "2014_christmas_team_mvp_toy_count_yesterday_" .. get_flag( "2014_christmas_team_yesterday" ) ) ) or 0

				text = "@90606350"
				if christmas_toy_count_yesterday >= 5 and christmas_toy_count_yesterday < 10 then
					insert_item( 2013548, 1 )
					text = "@90606349"
				elseif christmas_toy_count_yesterday >= 10 and christmas_toy_count_yesterday < 20 then
					insert_item( 2013548, 1 )
					insert_item( 2013548, 1 )
					text = "@90606349"
				elseif christmas_toy_count_yesterday >= 20 then
					insert_item( 2013548, 1 )
					insert_item( 2013548, 1 )
					insert_item( 2013548, 1 )
					text = "@90606349"
				end
			end

			if is_mvp() == true then
				insert_item( 2013562, 1 )		
				text = "@90606351"
			end

			del_flag( "2014_christmas_toy_count_yesterday" )
		end

		if is_last_day() == true then
			if is_final_winning_team() then
				insert_item( 2013563, 1 )
			end

			del_flag( "2014_christmas_team" )
			christmas_team = 0
		end

		-- 해로운 지속효과는 쌓인 횟수에 비례하여 지속시간이 증가하고 자동으로 부여된다. 피할 수 없다.
		for item_code, state_code in pairs( PixieItem.harmful_state_code ) do
			local key = "2014_christmas_" .. item_code
			local team_value = tonumber( get_global_variable( key .. "_" .. christmas_team ) ) or 0
			local value = tonumber( get_flag( key ) ) or 0
			local reiteration = team_value - value
			if reiteration > 0 then
				NPC_Event_2014_christmas_pixie_add_harmful_state( title, item_code, reiteration )
			end
		end

		-- 상대 팀에 의해 우리 팀의 요정이 잠에 빠졌다.
		local christmas_casting_team = get_global_variable( "2014_christmas_casting_team" )
		if get_state_level( 41103069 ) >= 1 and christmas_team ~= christmas_casting_team then
			dlg_text( "@90606383" )
			dlg_menu( "@90010002", " " )	--대화 종료
			dlg_show()
			return
		end

		dlg_text( "@90606336" ) -- 심술쟁이 요정 대사
		if text ~= nil then
			dlg_text( text )
		end

		dlg_menu( "@90606337", "NPC_Event_2014_christmas_pixie_ment1('" .. title .. "')" ) -- 메뉴 1 : 설명듣기
		dlg_menu( "@90606341", "NPC_Event_2014_christmas_pixie_toygive('" .. title .. "')" ) -- 장난감 건네기
		dlg_menu( "@90606357", "NPC_Event_2014_christmas_pixie_item_give_dialog('" .. title .. "')" ) -- 마법의 아이템 건네기

		for item_code, state_code in pairs( PixieItem.helpful_state_code ) do
			local key = "2014_christmas_" .. item_code
			local team_value = tonumber( get_global_variable( key .. "_" .. christmas_team ) ) or 0
			local value = tonumber( get_flag( key ) ) or 0
			if team_value - value > 0 then
				local text = sconv( "@90606386", "#@effect_item@#", "@" .. get_item_name_id( item_code ), "#@effect_receive_count@#", team_value - value )
				dlg_menu( text, "NPC_Event_2014_christmas_pixie_add_helpful_state('" .. title .. "'," .. item_code .. ")" )
			end
		end
	else
		dlg_text( "@90606381" ) -- 팀이 다를 경우
	end

	dlg_menu( "@90010002", " " )	--대화 종료
	dlg_show()
end 

