function NPC_Event_2014_christmas_toy_give( title, deleted_item_count )
	dlg_title( title ) -- 심술쟁이 요정
	dlg_text( "@90606346" )
	dlg_menu( "@90010003", "NPC_Event_2014_christmas_pixie(" .. get_flag( "2014_christmas_team" ) .. ", '" .. title .. "')" ) -- 돌아가기
	dlg_menu( "@90010002", " " ) -- 대화 종료
	dlg_show()

	local item_count = find_item( 2013549 ) -- 장난감 부품
	if deleted_item_count == 0 then
		deleted_item_count = item_count
	end

	if deleted_item_count == 0 or item_count < deleted_item_count then
		NPC_Event_2014_christmas_fail( title )
		return
	end

	-- 전달 및 공지
	local christmas_team = get_flag( "2014_christmas_team" )
	local notice_message = sconv( "@1272", "#@christmas_team@#", get_christmas_team_name( christmas_team ) )
	donate( 2013549, deleted_item_count, "2014_christmas_toy_count", "2014_christmas_team_toy_count_", christmas_team, notice_message, "#@team_toy_count@#", 100, 10 )
end

