	local christmas_team = get_flag( "2014_christmas_team" )
	local count = math.random( 2, 7 )
	local notice_message = sconv( "@1272", "#@christmas_team@#", get_christmas_team_name( christmas_team ) )
	donate( nil, count, "2014_christmas_toy_count", "2014_christmas_team_toy_count_", christmas_team, notice_message, "#@team_toy_count@#", 100, 10 )
end

function DancingDoll:affect()
	-- 전달 및 공지
	local christmas_team = get_flag( "2014_christmas_team" )
	local count = tonumber( get_global_variable( "2014_christmas_team_toy_count_today_" .. christmas_team ) ) or 0
	local notice_message = sconv( "@1272", "#@christmas_team@#", get_christmas_team_name( christmas_team ) )
	count = math.floor( count * 0.05 )
	donate( nil, count, "2014_christmas_toy_count", "2014_christmas_team_toy_count_", christmas_team, notice_message, "#@team_toy_count@#", 100, 10 )
end

