function NPC_Event_2015_Valentine_qupid_change_bouquet( change_type )

local deleted_item_count = find_item ( 2013571 )

	dlg_title( "@90606388" )
	dlg_text( "@90606406" )	-- 붉은장미꽃 교환 선택 시 대사
	
	if change_type == 1 then -- 10개 교환하기
	
		if deleted_item_count >= 10 then 
			insert_item( 2013574, 1 )
			delete_item( get_item_handle( 2013571 ), 10 )
	
		else
			NPC_Event_2015_Valentine_qupid_change_fail()
		end
		
		
	elseif change_type == 2 then -- 20개 교환하기
	
		if deleted_item_count >= 20 then 
			insert_item( 2013574, 2 )
			delete_item( get_item_handle( 2013571 ), 20 )
	
		else
			NPC_Event_2015_Valentine_qupid_change_fail()
		end
	
	elseif change_type == 3 then -- 50개 교환하기
	
		if deleted_item_count >= 50 then 
			insert_item( 2013574, 5 )
			delete_item( get_item_handle( 2013571 ), 50 )
	
		else
			NPC_Event_2015_Valentine_qupid_change_fail()
		end
	
	elseif change_type == 0 then -- 전부 교환하기
	
			item_count = math.floor ( deleted_item_count / 10 )
			delete_count= math.floor ( item_count * 10 )
	
		if deleted_item_count >= 10 then 
			insert_item( 2013574, item_count )
			delete_item( get_item_handle( 2013571 ), delete_count )
	
		else
			NPC_Event_2015_Valentine_qupid_change_fail()
		end
	
	end	
	
	dlg_menu( "@90010003", "NPC_Event_2015_Valentine_qupid_change()" )	-- 돌아가기
